CREATE TEMPORARY VIEW category_cluster_${grass_region_without_quote} AS
SELECT
    l1_category
    ,MAX(cluster) AS cluster
FROM
    mkplsearch_data_product.global_category_cluster_mapping
WHERE
    tree_type = 'global'
GROUP BY
    1;

--sql_divide_splitter--

CREATE TEMPORARY VIEW item_cats_${grass_region_without_quote} AS
SELECT
    item_id
    ,level1_global_be_category
    ,level2_global_be_category
    ,level3_global_be_category
FROM
    srdi_mart.dim_sr_data_warehouse_item
WHERE
    grass_region = ${grass_region}
    AND local_date = ${local_date};

--sql_divide_splitter--

CREATE TEMPORARY VIEW parse_data_${grass_region_without_quote} AS
SELECT
    COALESCE(keyword, '') AS keyword 
    ,COALESCE(CAST(is_ads AS STRING), 'false') AS is_ads
    ,item_id
    ,place_order_gmv
    ,place_order_gmv_local
    ,operation
    ,operation_cnt
FROM
    srdi_mart.dwd_sr_data_warehouse_search
WHERE
    grass_region = ${grass_region}
    AND local_date = ${local_date}
    AND page_type IN ('global_search', 'search_in_pdp', 'search_prefill')
    AND page_section IS NULL
    AND target_type = 'item'
    AND operation IN ('impression', 'ppv', 'cart', 'order');

--sql_divide_splitter--

CREATE TEMPORARY VIEW row_metrics_${grass_region_without_quote} AS
SELECT
    keyword
    ,cluster
    ,level1_global_be_category
    ,level2_global_be_category
    ,level3_global_be_category
    ,is_ads
    ,SUM(CASE WHEN operation = 'impression' THEN operation_cnt ELSE NULL END) AS item_imp_cnt
    ,SUM(CASE WHEN operation = 'ppv' THEN operation_cnt ELSE NULL END) AS item_pdp_cnt
    ,SUM(CASE WHEN operation = 'cart' THEN operation_cnt ELSE NULL END) AS atc_cnt
    ,SUM(CASE WHEN operation = 'order' THEN operation_cnt ELSE NULL END) AS place_order_cnt
    ,SUM(CASE WHEN operation = 'order' THEN place_order_gmv_local ELSE NULL END) AS place_order_gmv_local
    ,SUM(CASE WHEN operation = 'order' THEN place_order_gmv ELSE NULL END) AS place_order_gmv_usd
FROM
    parse_data_${grass_region_without_quote} a
JOIN
    item_cats_${grass_region_without_quote} b
ON
    a.item_id = b.item_id
LEFT JOIN
    category_cluster_${grass_region_without_quote} c
ON
    b.level1_global_be_category = c.l1_category
GROUP BY
    1,2,3,4,5,6;

--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_search_keyword_item_category_metrics_1d
PARTITION (
    grass_region = ${grass_region}
    ,local_date = ${local_date}
)
SELECT
    keyword
    ,cluster
    ,level1_global_be_category
    ,level2_global_be_category
    ,level3_global_be_category
    ,IF(is_ads IS NOT NULL, is_ads, '__ALL__')
    ,SUM(COALESCE(item_imp_cnt, 0))
    ,SUM(COALESCE(item_pdp_cnt, 0))
    ,SUM(COALESCE(atc_cnt, 0))
    ,SUM(COALESCE(place_order_cnt, 0))
    ,SUM(COALESCE(place_order_gmv_local, 0))
    ,SUM(COALESCE(place_order_gmv_usd, 0))
FROM
    row_metrics_${grass_region_without_quote}
GROUP BY GROUPING SETS
    (
        (keyword, cluster, level1_global_be_category, level2_global_be_category, level3_global_be_category, is_ads)
        ,(keyword, cluster, level1_global_be_category, level2_global_be_category, level3_global_be_category)
    );
